node --input-type=module - <<'JS'
import {readFile,writeFile} from 'node:fs/promises';import{spawn}from'node:child_process';
const p=JSON.parse(await readFile('.local/smart-shorts-audio/project-before.json','utf8'));const record=p.__opencutEditorSession;const r=JSON.parse(record);const t=performance.now();const child=spawn('./target/release/opencut-session-policy',[],{stdio:['pipe','pipe','pipe']});let n=0;child.stdout.on('data',b=>n+=b.length);child.stderr.on('data',b=>console.error(b.toString()));child.stdin.end(JSON.stringify({record,accountId:r.accountId,projectId:r.projectId,request:{type:'commit',sessionId:r.lease.sessionId,generation:r.generation,expectedStorageRevision:r.storageRevision,requestId:'isolated-audio-save-probe',bundle:r.saved.bundle},nowMs:r.lastHostTimeMs}));child.on('close',async code=>{const result={code,seconds:(performance.now()-t)/1000,outputBytes:n};console.log(result);await writeFile('.local/smart-shorts-audio/native-policy-probe.json',JSON.stringify(result));});
